  @protected
  void sse_encode_core_error(CoreError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CoreError_Network(message: final message):
        sse_encode_i_32(0, serializer);
        sse_encode_String(message, serializer);
      case CoreError_GitHub(status: final status, message: final message):
        sse_encode_i_32(1, serializer);
        sse_encode_u_16(status, serializer);
        sse_encode_String(message, serializer);
      case CoreError_Integrity(message: final message):
        sse_encode_i_32(2, serializer);
        sse_encode_String(message, serializer);
      case CoreError_InvalidInput(message: final message):
        sse_encode_i_32(3, serializer);
        sse_encode_String(message, serializer);
      case CoreError_Io(message: final message):
        sse_encode_i_32(4, serializer);
        sse_encode_String(message, serializer);
      case CoreError_DecryptFailed():
        sse_encode_i_32(5, serializer);
      case CoreError_Crypto():
        sse_encode_i_32(6, serializer);
    }
  }

  @protected
  void sse_encode_download_progress(
    DownloadProgress self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case DownloadProgress_Downloading(
        received: final received,
        total: final total,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_64(received, serializer);
        sse_encode_u_64(total, serializer);
      case DownloadProgress_Verifying():
        sse_encode_i_32(1, serializer);
      case DownloadProgress_Done(path: final path, sha256: final sha256):
        sse_encode_i_32(2, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(sha256, serializer);
    }
  }

